#include <vector>
#include <algorithm>

class Solution {
public:
    std::vector<std::vector<int>> flipSubmatrix(std::vector<std::vector<int>>& grid, int x, int y, int k) {
        for (int r = 0; r < k / 2; ++r) {
            int r1 = x + r;
            int r2 = x + k - 1 - r;
            for (int c = 0; c < k; ++c) {
                int c_idx = y + c;
                std::swap(grid[r1][c_idx], grid[r2][c_idx]);
            }
        }
        return grid;
    }
};

class Solution {
    public int[][] flipSubmatrix(int[][] grid, int x, int y, int k) {
        for (int r = 0; r < k / 2; r++) {
            int r1 = x + r;
            int r2 = x + k - 1 - r;
            for (int c = 0; c < k; c++) {
                int cIdx = y + c;
                int temp = grid[r1][cIdx];
                grid[r1][cIdx] = grid[r2][cIdx];
                grid[r2][cIdx] = temp;
            }
        }
        return grid;
    }
}

var flipSubmatrix = function(grid, x, y, k) {
    for (let r = 0; r < Math.floor(k / 2); r++) {
        const r1 = x + r;
        const r2 = x + k - 1 - r;
        for (let c = 0; c < k; c++) {
            const cIdx = y + c;
            const temp = grid[r1][cIdx];
            grid[r1][cIdx] = grid[r2][cIdx];
            grid[r2][cIdx] = temp;
        }
    }
    return grid;
};
